// @vitest-environment node
// Synthetic material generated by the actual Windows preparer, never operator files.
import { mkdtempSync, rmSync, writeFileSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { basename, dirname, join, resolve } from 'node:path'
import { spawnSync } from 'node:child_process'
import { expect, it } from 'vitest'
import { createPrivateFiscalCustody } from '../../supabase/functions/_shared/fiscalPrivateCustody'
import { prepareWsaaRequest } from '../../supabase/functions/_shared/fiscalWsaaCms'
import type { FiscalWorkerBinding } from '../../supabase/functions/_shared/fiscalWorkerAuthorization'

const quote = (value: string) => `'${value.replaceAll("'", "''")}'`
function cleanupSyntheticRoot(root: string): void {
  const target = resolve(root)
  if (dirname(target) !== resolve(tmpdir()) || !basename(target).startsWith('kiosko-dotnet-custody-test-')) throw Error('Unexpected synthetic test target')
  rmSync(target, { recursive: true, force: true })
}

it.skipIf(process.platform !== 'win32')('importa PKCS8 cifrado real .NET con contraseña Unicode, firma CMS y falla cerrado con otra contraseña', async () => {
  const root = mkdtempSync(join(tmpdir(), 'kiosko-dotnet-custody-test-'))
  // This known test-only passphrase is never used for real credentials.
  const syntheticPassword = 'SYNTHETIC_only_á_🔐_password_2026'
  try {
    const runner = join(root, 'interop.ps1')
    writeFileSync(runner, `
$ErrorActionPreference='Stop'
. ${quote(resolve('scripts/preparar-arca-homologacion.ps1'))}
$phrase=ConvertTo-SecureString ${quote(syntheticPassword)} -AsPlainText -Force
try {
 $fixture=New-ArcaHomologationRequest -Cuit '20123456786' -Organizacion 'Synthetic' -Alias 'KioskoInterop' -Clave $phrase -Confirmacion $phrase -Directorio ${quote(join(root, 'private-synthetic'))}
 Add-Type @'
using System;using System.IO;using System.Security.Cryptography;using System.Security.Cryptography.X509Certificates;
public static class SyntheticInteropCertificate {
 public static string Issue(string csrPath) {
  using var caKey=RSA.Create(2048);
  var caRequest=new CertificateRequest("CN=Computadores Test",caKey,HashAlgorithmName.SHA256,RSASignaturePadding.Pkcs1);
  caRequest.CertificateExtensions.Add(new X509BasicConstraintsExtension(true,false,0,true));
  var now=DateTimeOffset.UtcNow;
  using var ca=caRequest.CreateSelfSigned(now.AddDays(-1),now.AddDays(1));
  var request=CertificateRequest.LoadSigningRequestPem(File.ReadAllText(csrPath),HashAlgorithmName.SHA256,CertificateRequestLoadOptions.Default,RSASignaturePadding.Pkcs1);
  using var leaf=request.Create(ca,now.AddHours(-1),now.AddHours(1),new byte[]{1});
  return leaf.ExportCertificatePem();
 }
}
'@
 [pscustomobject]@{certificate=[SyntheticInteropCertificate]::Issue($fixture.Solicitud);encryptedKey=[IO.File]::ReadAllText($fixture.ClaveCifrada)} | ConvertTo-Json -Compress
} finally {$phrase.Dispose()}
`)
    const generated = spawnSync('pwsh', ['-NoProfile', '-NonInteractive', '-File', runner], { encoding: 'utf8', timeout: 30000 })
    // Do not include stdout (synthetic PEMs) in diagnostics.
    expect(generated.status, generated.stderr).toBe(0)
    const fixture = JSON.parse(generated.stdout.trim()) as { certificate: string; encryptedKey: string }
    expect(fixture.encryptedKey.startsWith('-----BEGIN ENCRYPTED PRIVATE KEY-----')).toBe(true)
    const certificateBase64 = fixture.certificate.replace(/-----[^\r\n]+-----|\s/g, '')
    const fingerprint = Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256', Uint8Array.from(atob(certificateBase64), character => character.charCodeAt(0)))), byte => byte.toString(16).padStart(2, '0')).join('')
    const credentialId = crypto.randomUUID(), prefix = 'ARCA_HOMO_CREDENTIAL_' + credentialId.replaceAll('-', '').toUpperCase()
    const secrets: Record<string, string> = {
      SUPABASE_URL: 'https://acoyfwwmhaeruciyedri.supabase.co',
      [prefix + '_REVISION']: '1', [prefix + '_CERT_PEM']: fixture.certificate,
      [prefix + '_KEY_PEM']: fixture.encryptedKey, [prefix + '_PASSWORD']: syntheticPassword,
    }
    const binding: FiscalWorkerBinding = {
      version: 1, entorno: 'HOMOLOGACION', servicio: 'wsfe', operacion_id: crypto.randomUUID(),
      kiosco_id: crypto.randomUUID(), usuario_id: crypto.randomUUID(), cuit_emisor: '20123456786', punto_venta: 2,
      credencial_id: credentialId, certificado_sha256: fingerprint, revision: 1,
    }
    const custody = createPrivateFiscalCustody(name => secrets[name])
    const material = await custody(binding, new AbortController().signal)
    expect(material.privateKey.extractable).toBe(false)
    expect((material.privateKey.algorithm as RsaHashedKeyAlgorithm).modulusLength).toBe(3072)
    await expect(crypto.subtle.exportKey('pkcs8', material.privateKey)).rejects.toThrow()
    expect(JSON.stringify(material)).toBe(JSON.stringify({ credentialId }))
    const cms = await prepareWsaaRequest(material, { credentialId, certificateSha256: fingerprint })
    expect(cms.cmsDer.length).toBeGreaterThan(100)
    expect(JSON.stringify(cms)).not.toMatch(/PRIVATE KEY|SYNTHETIC|cmsDer/)
    const wrongPassword = { ...secrets, [prefix + '_PASSWORD']: 'SYNTHETIC_WRONG_PASSWORD_2026' }
    await expect(createPrivateFiscalCustody(name => wrongPassword[name])(binding, new AbortController().signal)).rejects.toThrow('FISCAL_CUSTODIA_NO_DISPONIBLE')
  } finally {
    cleanupSyntheticRoot(root)
  }
}, 40000)
